create or replace function get_schedule_activity_instances_v1() returns table(activity_key text,teacher_assignment_id uuid,component_no smallint,duration smallint,teacher_id uuid,class_id uuid,course_id uuid) language sql stable as $$with base as(select a.teacher_assignment_id,a.teacher_id,a.class_id,a.course_id,a.assigned_hours,r.block_pattern,coalesce((select sum(v) from unnest(r.block_pattern) v),0) pattern_sum from schedule_assignment_options a left join course_schedule_rules r on r.course_id=a.course_id and r.active and tenant_row_allowed(r.institution_code)),parts as(select b.teacher_assignment_id,b.teacher_id,b.class_id,b.course_id,x.n::smallint component_no,x.d::smallint duration from base b cross join lateral(select ord::int n,val::int d from unnest(b.block_pattern) with ordinality u(val,ord) where b.pattern_sum=b.assigned_hours and b.pattern_sum>0 union all select g,1 from generate_series(1,b.assigned_hours) g where b.pattern_sum<>b.assigned_hours or b.pattern_sum=0)x) select teacher_assignment_id::text||':'||component_no,teacher_assignment_id,component_no,duration,teacher_id,class_id,course_id from parts order by teacher_assignment_id,component_no$$;